package com.mathew.blackseaquest

import kotlinx.browser.document
import org.w3c.dom.HTMLDivElement

fun main() {
    // Ищем контейнер на странице (тот самый ComposeTarget, который мы добавляли в HTML)
    val root = document.getElementById("ComposeTarget") as? HTMLDivElement
    
    if (root != null) {
        // Просто выводим текст, чтобы проверить, что JS работает
        root.innerHTML = """
            <div style="text-align: center; padding: 50px; font-family: sans-serif;">
                <h1 style="color: #0D47A1;">Игра Матвея (JS-версия)</h1>
                <p>Если вы видите этот текст в MAX, значит, проблема была в Wasm!</p>
                <button style="padding: 10px 20px; font-size: 16px; background: #0D47A1; color: white; border: none; border-radius: 5px; cursor: pointer;">
                    Бросить кубик
                </button>
            </div>
        """.trimIndent()
    } else {
        // Если контейнера нет, создаем его сами
        val newRoot = document.createElement("div") as HTMLDivElement
        newRoot.id = "ComposeTarget"
        newRoot.innerHTML = "<h1>Игра Матвея (JS-версия)</h1><p>Контейнер создан автоматически.</p>"
        document.body?.appendChild(newRoot)
    }
}